CASES = []


def add_case(slug, subindustries, name, modes, question, action, actors, unit, population, grain,
             systems, shapes, methods, operations, inputs, outputs, assumptions, invariants,
             failures, evidence, limitations, llm="none", time=None):
    CASES.append({
        "record_id": f"commerce.case.{slug}",
        "record_kind": "analytical_case",
        "edition": EDITION,
        "status": "sourced_candidate",
        "industry_id": INDUSTRY,
        "subindustry_ids": subindustries,
        "name": name,
        "analytical_modes": modes,
        "sovereign_question": question,
        "decision_or_action": action,
        "actors": actors,
        "unit_of_analysis": unit,
        "population": population,
        "grain": grain,
        "time_model": time or ["event time", "decision time", "effective time", "recorded time", "analysis cut"],
        "source_system_refs": systems,
        "data_shape_refs": shapes,
        "method_refs": methods,
        "operation_refs": operations,
        "inputs": inputs,
        "outputs": outputs,
        "assumptions": assumptions,
        "invariants": invariants,
        "failure_modes": failures,
        "evidence_refs": evidence,
        "llm_dependency": llm,
        "limitations": limitations,
    })


# Analytical cases are appended below by subindustry.  Each is a question/decision
# contract; none is merely a metric name.

MODE_METHOD = {
    "operational": "analytics.method.state_and_exception_monitoring",
    "diagnostic": "analytics.method.stratified_drilldown_and_decomposition",
    "root_cause": "analytics.method.causal_graph_and_root_cause_analysis",
    "process": "analytics.method.process_mining_and_conformance",
    "bottleneck": "analytics.method.queueing_and_constraint_analysis",
    "causal": "analytics.method.causal_inference",
    "experimental": "analytics.method.randomized_controlled_experiment",
    "forecasting": "analytics.method.probabilistic_forecasting",
    "anomaly": "analytics.method.change_point_and_anomaly_detection",
    "optimization": "analytics.method.constrained_mathematical_optimization",
    "simulation": "analytics.method.discrete_event_and_scenario_simulation",
    "pricing": "analytics.method.elasticity_and_choice_estimation",
    "recommendation": "analytics.method.ranking_and_recommendation",
    "segmentation": "analytics.method.clustering_and_latent_class_analysis",
    "survival": "analytics.method.survival_and_hazard_modeling",
    "reliability": "analytics.method.reliability_and_failure_analysis",
    "spatial": "analytics.method.spatial_network_analysis",
    "risk": "analytics.method.risk_scoring_and_calibration",
    "fraud": "analytics.method.graph_and_behavioral_anomaly_detection",
    "text": "analytics.method.text_speech_and_thematic_analysis",
    "vision": "analytics.method.computer_vision_detection_and_tracking",
    "llm_optional": "analytics.method.quarantined_llm_generation_with_tevv",
}


def register_cases(subindustries, default_actors, default_systems, default_shapes, default_evidence, specs):
    """Expand concise, domain-reviewed specs into the shared research record."""
    for spec in specs:
        modes = spec["modes"]
        methods = list(dict.fromkeys(spec.get("methods", []) + [MODE_METHOD[m] for m in modes]))
        operations = list(dict.fromkeys(spec.get("operations", []) + [
            "operation.authorized_source_cut",
            "operation.asof_identity_and_dimension_join",
            "operation.reconcile_native_grains",
            "operation.estimate_with_uncertainty",
            "operation.issue_evidence_bound_proposal",
            "operation.observe_action_outcome",
        ]))
        systems = list(dict.fromkeys(default_systems + spec.get("systems", [])))
        shapes = list(dict.fromkeys(default_shapes + spec.get("shapes", [])))
        evidence = list(dict.fromkeys(default_evidence + spec.get("evidence", [])))
        add_case(
            spec["slug"], spec.get("subindustries", subindustries), spec["name"], modes,
            spec["q"], spec["a"], spec.get("actors", default_actors), spec["unit"],
            spec.get("population", f"All in-scope {spec['unit']} observations under the stated business, geography, channel and time cut; exclusions are published."),
            spec.get("grain", f"Native {spec['unit']} event/state grain, preserved before any decision-level aggregation."),
            systems, shapes, methods, operations,
            spec.get("inputs", ["authorized native-grain observations from referenced systems", "effective-dated policies, constraints and entity mappings", "intervention/decision history and later outcomes"]),
            spec.get("outputs", ["ranked diagnosis or feasible decision proposal", "uncertainty, sensitivity and affected-population breakdown", "source cut, method/version, constraint and approval receipt"]),
            ["source timestamps and correction semantics are recoverable", "population, treatment/decision eligibility and outcome windows are declared", "unobserved demand or behavior is not equated with zero"] + spec.get("assumptions", []),
            ["accepted commercial obligations and historical observations are never rewritten by a model", "legal, safety, consent, labor and contractual constraints dominate objective value", "model output has no write authority without the named actor/workflow"] + spec.get("invariants", []),
            ["source latency, missingness or semantic drift", "selection, survivorship or identity-link bias", "policy change or feedback loop mistaken for stable behavior"] + spec.get("failures", []),
            evidence,
            ["Candidate cross-enterprise pattern; local policy, feasibility, identification assumptions and acceptance thresholds require adjudication."] + spec.get("limitations", []),
            spec.get("llm", "quarantined_optional" if "llm_optional" in modes else "none"),
            spec.get("time"),
        )


