def emit():
    files = {
        "sources.jsonl": SOURCES,
        "source-systems.jsonl": SYSTEMS,
        "data-shapes.jsonl": SHAPES,
        "analytics-cases.jsonl": CASES,
    }
    for name, rows in files.items():
        with (ROOT / name).open("w", encoding="utf-8") as handle:
            for row in rows:
                handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n")

    manifest = {
        "pack_id": "commerce_services.research_pack",
        "edition": EDITION,
        "status": "sourced_candidate",
        "generated_at": ACCESSED,
        "record_counts": {name: len(rows) for name, rows in files.items()},
        "subindustry_case_counts": dict(sorted(Counter(s for c in CASES for s in c["subindustry_ids"]).items())),
        "analytical_mode_counts": dict(sorted(Counter(m for c in CASES for m in c["analytical_modes"]).items())),
        "llm_dependency_counts": dict(sorted(Counter(c["llm_dependency"] for c in CASES).items())),
        "research_contract": "../schema/industry-research-record.schema.json",
    }
    (ROOT / "manifest.json").write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    emit()
